CREATE TABLE stock_command_receipt(id BIGINT AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT NOT NULL,operation_code VARCHAR(64) NOT NULL,request_key VARCHAR(128) NOT NULL,actor_id BIGINT NOT NULL,request_hash CHAR(64) NOT NULL,response_json LONGTEXT,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL,completed_at TIMESTAMP,UNIQUE(institution_id,operation_code,request_key),CHECK((completed_at IS NULL AND response_json IS NULL) OR (completed_at IS NOT NULL AND response_json IS NOT NULL)));
